import type { MediaAsset, Provenance } from "../types";
import published from "./published-assets.json";

/** Published, approved media + sanitized provenance. Generated by scripts/history-media/publish.mjs. */
const data = published as unknown as { generatedAt: string; assets: MediaAsset[]; provenance: Provenance[] };

const ASSETS = new Map(data.assets.map((a) => [a.id, a]));
const PROV = new Map(data.provenance.map((p) => [p.id, p]));

export const getAsset = (id: string | undefined) => (id ? ASSETS.get(id) : undefined);
export const getProvenance = (id: string | undefined) => (id ? PROV.get(id) : undefined);
export const PUBLISHED_AT = data.generatedAt;
